.logo h1 {
    font-size: 1.8rem;
    color: #bb86fc;
}

.nav ul {
    display: flex;
    list-style: none;
}

.nav li {
    margin-left: 2rem;
}

.nav a {
    text-decoration: none;
    color: #e0e0e0;
    font-weight: 500;
    transition: color 0.3s;
}

.nav a:hover {
    color: #03dac6;
}

/* Hero */
.hero {
    background: linear-gradient(135deg, #6a11cb 0%, #2575fc 100%);
    color: white;
    text-align: center;
    padding: 6rem 2rem;
