.hero h2 {
    font-size: 2.5rem;
    margin-bottom: 1rem;
}

.hero p {
    font-size: 1.2rem;
    margin-bottom: 2rem;
    opacity: 0.9;
}

.btn-primary {
    display: inline-block;
    background: #1e1e1e;
    color: #bb86fc;
    padding: 0.8rem 2rem;
    border-radius: 50px;
    text-decoration: none;
    font-weight: 600;
    transition: transform 0.3s, box-shadow 0.3s, border 0.3s;
    border: 2px solid #bb86fc;
}

.btn-primary:hover {
    transform: translateY(-3px);
    box-shadow: 0 5px 15px rgba(0,0,0,0.3);
    background: #2d2d2d;
}

/* Features */
.features {
    padding: 4rem 0;
    background-color: #1e1e1e;
}

.features h2 {
    text-align: center;
    margin-bottom: 3rem;
    color: #bb86fc;
    font-size: 2rem;
}

.features-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 2rem;
}

.feature-card {
    background: #2d2d2d;
    padding: 2rem;
    border-radius: 10px;
    text-align: center;
    transition: transform 0.3s, box-shadow 0.3s;
    border: 1px solid #3d3d3d;
}

.feature-card:hover {
    transform: translateY(-5px);
    box-shadow: 0 10px 20px rgba(0,0,0,0.2);
}

.feature-card h3 {
    color: #bb86fc;
    margin-bottom: 0.8rem;
    font-size: 1.3rem;
}

.feature-card p {
    color: #b0b0b0;
}

/* Download */
.download {
    background-color: #1e1e1e;
    padding: 4rem 0;
    text-align: center;
}

.download h2 {
    margin-bottom: 1.5rem;
    color: #bb86fc;
    font-size: 2rem;
}

.download p {
    margin-bottom: 2rem;
    color: #b0b0b0;
    max-width: 600px;
    margin-left: auto;
    margin-right: auto;
}

.download-buttons {
    display: flex;
    justify-content: center;
    gap: 1rem;
    flex-wrap: wrap;
    margin-bottom: 2rem;
}

.btn-secondary {
    display: inline-block;
    background: #03dac6;
    color: #121212;
    padding: 0.9rem 2.5rem;
    border-radius: 50px;
    text-decoration: none;
    font-weight: 600;
    transition: background 0.3s, transform 0.3s;
}

.btn-secondary:hover {
    background: #01b3a4;
    transform: translateY(-3px);
}

.download-note {
    font-size: 0.9rem;
    color: #808080;
}

/* About */
.about {
    padding: 4rem 0;
    background-color: #1e1e1e;
}

.about h2 {
    text-align: center;
    margin-bottom: 2rem;
    color: #bb86fc;
    font-size: 2rem;
}

.about p {
    max-width: 800px;
    margin: 0 auto 1.5rem auto;
    color: #b0b0b0;
    line-height: 1.8;
}

/* Footer */
.footer {
    background-color: #1e1e1e;
    color: #e0e0e0;
    text-align: center;
    padding: 2rem 0;
}

.footer p {
    margin-bottom: 1rem;
}

.footer-links a {
    color: #bb86fc;
    margin: 0 1rem;
    text-decoration: none;
    transition: color 0.3s;
}

.footer-links a:hover {
    color: #03dac6;
}

/* Responsive */
@media (max-width: 768px) {
    .header .container,
    .nav ul {
        flex-direction: column;
    }

    .nav li {
        margin: 0.5rem 0;
    }

    .hero h2 {
        font-size: 2rem;
    }

    .hero p {
        font-size: 1rem;
    }

    .features-grid {
        grid-template-columns: 1fr;
    }

    .download-buttons {
        flex-direction: column;
        align-items: center;
    }
}

